/* Types */
/**  What About and the bell show; `available` is false on every platform but an Android release build. */
export type ApkUpdateState = {
	available: boolean,
	/**  `none` · `downloading` · `ready` · `blocked`. */
	status: string,
	version: string | null,
	/**  For `blocked`: `metered` · `space` · `signature` · `stale` · `foreground` · `network`. */
	reason: string | null,
	needsInstallPermission: boolean,
	received: number,
	total: number,
};

export type AuthInfo = {
	/**  true if a client ID is compiled in (login works without any setup) */
	hasBuiltinClientId: boolean,
	customClientId: string | null,
	/**  The redirect URL an API client must register, built from `login::AUTH_CALLBACK_PORT` so the port has one origin. */
	callbackUrl: string,
};

export type BackupSettings = {
	enabled: boolean,
	keep: number,
	/**  Where the files land, shown in the settings hint so nobody has to ask. */
	dir: string,
};

/**  Which of the two addresses a request went to. */
export type Base = "local" | "external";

/**  What a bulk edit managed and what stopped it; two fields, because a run can both write hundreds and fail. */
export type BulkResult = BulkResult_Serialize | BulkResult_Deserialize;

/**  What a bulk edit managed and what stopped it; two fields, because a run can both write hundreds and fail. */
export type BulkResult_Deserialize = {
	updated: number,
	/**  The failure that ended the run; whatever `updated` counts is already written and not undone by it. */
	error: string | null,
};

/**  What a bulk edit managed and what stopped it; two fields, because a run can both write hundreds and fail. */
export type BulkResult_Serialize = {
	updated: number,
	/**  The failure that ended the run; whatever `updated` counts is already written and not undone by it. */
	error?: string | null,
};

/**  One change for many entries; a struct because specta's function support stops at ten arguments. */
export type BulkSaveInput = {
	ids: number[],
	status: string | null,
	/**  The format-independent raw score, never a float. */
	scoreRaw: number | null,
	progress: number | null,
	progressVolumes: number | null,
	repeat: number | null,
	private: boolean | null,
	/**  `FuzzyDateInput`, forwarded as an opaque `{year, month, day}` because every part is nullable. */
	startedAt: any | null,
	completedAt: any | null,
};

/**  What the frontend asks the passthrough to cache: a TTL, and the media a detail answer is about so an edit evicts it. */
export type CacheOpts = {
	ttlSec: number,
	mediaId: number | null,
};

export type CloseToTray = {
	/**  What closing the window does right now. */
	enabled: boolean,
	/**  Whether a tray icon was created at startup, so the screen can say why the setting reads as it does. */
	tray: boolean,
};

/**  Enough about a database file to say how old it is and whether it looks used. */
export type DatabaseInfo = {
	path: string,
	bytes: number,
	/**  Last modified in milliseconds since the epoch, or 0 when the filesystem will not say. */
	modifiedMs: number,
};

/**  One detection correction: what was detected, and what it really is. */
export type DetectionOverride = {
	/**  The parsed title this fires on — what detection saw. */
	title: string,
	/**  `-1` where the parse carried no season. */
	season: number,
	mediaType: string,
	mediaId: number,
	/**  The chosen entry's title, stored so the Settings list and an off-list entry read correctly without a request. */
	displayTitle: string,
	/**  Added to the detected episode; signed because a source may number ahead of AniList as easily as behind. */
	episodeOffset: number,
};

export type Diagnostics = {
	/**  The four-part `MAJOR.MINOR.PATCH.COMMIT#`; the commit counter is the only precise build identifier. */
	version: string,
	os: string,
	appImage: boolean,
	portable: boolean,
	/**  Where the database lives; redacted by `render`, not here, so the viewer can show the owner the real path. */
	dataDir: string,
	tray: boolean,
	schema: number,
	/**  Which manifest the updater polls; the same four-part version can run on either channel. */
	updateChannel: string,
	queued: number,
	/**  Whether a token exists. Never the token. */
	signedIn: boolean,
	profileMode: string,
	libraryConfigured: boolean,
	libraryFiles: number,
	libraryMatched: number,
	mediaSessions: boolean,
	jellyfin: boolean,
	/**  Which Jellyfin address the last successful request went to, `local` or `external`; it names no host. */
	jellyfinBase: string | null,
	/**  The mpv IPC pipe; it outranks every other source, so a report has to say whether it was on. */
	mpv: boolean,
	logDebug: boolean,
	/**  AniList requests per source since the app started; the budget is shared, so a report has to say who spent it. */
	anilistRequests: ([string, number])[],
	/**  HTTP 429 answers since the app started. */
	anilistThrottled: number,
	/**  The limiter's last measured headroom, `remaining/limit`, or none before the first header. */
	anilistBudget: [number, number] | null,
	linux: LinuxInfo | null,
};

export type DiscordSettings = {
	enabled: boolean,
	appId: string,
	/**  true if an application ID is compiled in */
	hasBuiltinAppId: boolean,
};

/**  A server that answered the broadcast, confirmed by its own info endpoint. */
export type DiscoveredServer = {
	name: string,
	address: string,
	id: string,
	/**  From the probe; `None` for a reply that was never confirmed. */
	version: string | null,
};

export type DownloadedUpdate = {
	version: string,
	notes: string | null,
};

export type JellyfinBackground = {
	enabled: boolean,
	/**  Whether this platform has the service at all (Android only), so the pane can leave the rows out elsewhere. */
	supported: boolean,
	/**  Whether Android has exempted Karasu from battery optimisation; `None` where it does not apply or could not be asked. */
	batteryExempt: boolean | null,
};

export type JellyfinSettings = {
	url: string,
	/**  Whether an access token is stored; the token itself never leaves the credential store. */
	connected: boolean,
	/**  The signed-in account, so Settings can show who that is. */
	userName: string,
	/**  The server's own name from `/System/Info/Public` at sign-in; empty for a sign-in older than that probe. */
	serverName: string,
	device: string,
	/**  This machine's name, so the UI can offer it as the default. */
	localDevice: string,
	/**  The optional second address; empty for none. */
	externalUrl: string,
	/**  Whether the external address has answered as the same server from here; `None` when there is none. */
	externalVerified: boolean | null,
	/**  Whether the external address would carry the token over plain http, which the pane warns about. */
	externalPlainHttp: boolean,
};

/**  The Test-connection answer: the sessions, and which address answered. */
export type JellyfinTest = {
	sessions: SessionSummary[],
	base: Base,
	url: string,
};

/**  Severity, ordered `Error < Warn < Info < Debug`, so a threshold check is a plain comparison. */
export type Level = "error" | "warn" | "info" | "debug";

/**  Which episodes of a matched entry are on disk; `episodes` stays a bare sorted list for existing callers. */
export type LibraryEntry = LibraryEntry_Serialize | LibraryEntry_Deserialize;

/**  Which episodes of a matched entry are on disk; `episodes` stays a bare sorted list for existing callers. */
export type LibraryEntry_Deserialize = {
	mediaId: number,
	episodes: number[],
	files: LibraryFile[],
	/**  Matcher confidence; `1.0` is the exact-title short circuit and anything below reads as "close" on screen. */
	score: number,
	/**  The release names that led here — what a correction has to be keyed on. */
	sources: TitleKey[],
	/**  Placed by the user rather than the matcher, so the screen can say so instead of showing a confidence. */
	manual: boolean,
	/**  More files than the entry has episodes, usually a next season in one folder; detection only, nothing re-pointed. */
	overflow: Overflow_Deserialize | null,
};

/**  Which episodes of a matched entry are on disk; `episodes` stays a bare sorted list for existing callers. */
export type LibraryEntry_Serialize = {
	mediaId: number,
	episodes: number[],
	files: LibraryFile[],
	/**  Matcher confidence; `1.0` is the exact-title short circuit and anything below reads as "close" on screen. */
	score: number,
	/**  The release names that led here — what a correction has to be keyed on. */
	sources: TitleKey[],
	/**  Placed by the user rather than the matcher, so the screen can say so instead of showing a confidence. */
	manual: boolean,
	/**  More files than the entry has episodes, usually a next season in one folder; detection only, nothing re-pointed. */
	overflow?: Overflow_Serialize | null,
};

/**  One episode present on disk. */
export type LibraryFile = {
	episode: number,
	path: string,
};

/**  One confirmed split for the Settings list, keyed on the parse, which is what `clear_library_redirect` deletes by. */
export type LibraryRedirectRow = {
	title: string,
	season: number,
	epFrom: number,
	epTo: number,
	mediaId: number,
	dstStart: number,
};

/**  What the library screen's path row says, without needing a scan to say it. */
export type LibraryStatus = {
	path: string | null,
	/**  Video files the last scan walked past, matched or not. */
	filesSeen: number,
	/**  Titles it could identify. */
	matched: number,
};

/**  The Linux-only half; `None` on Windows, so the shape says which platform produced it. */
export type LinuxInfo = {
	/**  `PRETTY_NAME` from `/etc/os-release`. */
	distro: string | null,
	/**  `XDG_CURRENT_DESKTOP`; GNOME needs an extension before a tray icon appears at all. */
	desktop: string | null,
	/**  `XDG_SESSION_TYPE`; under Wayland one application cannot read another's window titles at all. */
	session: string | null,
};

export type ListResult = {
	/**  true if the data comes from the local cache (offline) */
	fromCache: boolean,
	/**  number of changes not yet synced */
	pending: number,
	/**  When this list was last fetched from AniList, unix seconds; the frontend seeds its own staleness from it. */
	fetchedAt: number,
	lists: any,
};

/**  One line; `target` is the subsystem, so the viewer can group without parsing the message. */
export type LogEntry = {
	ms: number,
	level: Level,
	target: string,
	message: string,
};

/**  One media session as the desktop sees it, serialized straight into the Settings diagnostic. */
export type MediaSession = {
	/**  Source app: an executable path or package family name on Windows, a D-Bus bus name on Linux. */
	appId: string,
	title: string,
	artist: string,
	album: string,
	/**  "music" | "video" | "image" | "unknown" */
	playbackType: string,
	/**  "playing" | "paused" | "stopped" | "changing" | "opened" | "closed" */
	status: string,
	/**  What is being played, when the source says; MPRIS publishes `xesam:url`, SMTC has no equivalent. */
	url: string,
};

export type MpvIpcSettings = {
	enabled: boolean,
	/**  The effective path — the stored one, or the platform default. */
	path: string,
	/**  What the settings hint tells the user to put in `mpv.conf`. */
	defaultPath: string,
	/**  The player binary for library launches, empty for the default player. */
	launchPath: string,
};

export type MutationResult = {
	/**  true if the change was queued offline */
	queued: boolean,
	entry: any | null,
};

/**  One in-app notification (mirrors a shown desktop toast). */
export type NotificationRow = {
	id: number,
	kind: string,
	title: string,
	body: string,
	createdMs: number,
	/**  What the bell row opens; `None` for the update notice, a dropped-queue report and every row older than v15. */
	mediaId: number | null,
	read: boolean,
};

export type NowPlaying = {
	process: string,
	streaming: boolean,
	/**  "ANIME" or "MANGA" — for manga, `episode` carries the chapter number */
	mediaType: string,
	rawTitle: string,
	parsedTitle: string,
	/**  The season the parse carried; half of a correction's key, so the picker has to send it back. */
	season: number | null,
	/**  The episode as resolved: the source's number plus any correction offset, then the relations redirect. */
	episode: number | null,
	/**  The episode as the source reported it; re-resolving from the shifted one would shift it again. */
	sourceEpisode: number | null,
	/**  AniList media ID on a successful match against the list */
	mediaId: number | null,
	matchedTitle: string | null,
	/**  Whether this match came from the user's own correction; drives the "undo" affordance, nothing else. */
	overridden: boolean,
	/**  Current list progress of the matched entry */
	progress: number | null,
	totalEpisodes: number | null,
	/**  The episode's own name where the source had one, for the card; never part of any key. */
	episodeTitle: string | null,
};

/**  The facts the season-split card needs, computed at reindex time. */
export type Overflow = Overflow_Serialize | Overflow_Deserialize;

/**  The facts the season-split card needs, computed at reindex time. */
export type Overflow_Deserialize = {
	/**  AniList's episode count for the matched entry. */
	knownEpisodes: number,
	/**  How many on-disk episodes lie beyond it. */
	extraFiles: number,
	/**  The first overflowing episode number, as the files spell it. */
	firstExtra: number,
	/**  What the community rules say the overflow is: a pre-selection for the card, never applied without confirmation. */
	hint: SplitHint | null,
};

/**  The facts the season-split card needs, computed at reindex time. */
export type Overflow_Serialize = {
	/**  AniList's episode count for the matched entry. */
	knownEpisodes: number,
	/**  How many on-disk episodes lie beyond it. */
	extraFiles: number,
	/**  The first overflowing episode number, as the files spell it. */
	firstExtra: number,
	/**  What the community rules say the overflow is: a pre-selection for the card, never applied without confirmation. */
	hint?: SplitHint | null,
};

/**  Which kind of Karasu a `/Sessions` row is; ordered, because a desktop outranks a phone and that order is the rule. */
export type Platform = "mobile" | "desktop";

/**  What the screen needs to know about where it runs; tray presence stays with `get_close_to_tray`, one source. */
export type PlatformInfo = {
	/**  "windows" | "linux" | "android", whatever `std::env::consts::OS` says. */
	os: string,
	/**  Running from an AppImage, the only Linux layout the updater can replace and portable mode can write beside. */
	appImage: boolean,
};

export type PortableStatus = {
	portable: boolean,
	/**  Absolute path where the database currently lives. */
	dir: string,
	/**  A database in the folder this switch would move away from; `None` when that folder holds nothing. */
	other: DatabaseInfo | null,
};

/**  One queued edit, described rather than replayed; the payload itself never crosses to the frontend. */
export type QueuedEdit = {
	id: number,
	/**  `"save"` or `"delete"`. */
	kind: string,
	/**  The media id for a save, the list-entry id for a delete, `None` when the payload does not parse but still a row. */
	subject: number | null,
	/**  The fields this edit changes, for the row's summary line. */
	fields: string[],
	queuedAt: number,
};

/**  What the sync panel shows about the limiter; local state only, so reading it costs no request. */
export type RateSnapshot = {
	/**  `None` until a response header has been seen this session. */
	remaining: number | null,
	limit: number | null,
	observedAgoMs: number | null,
	/**  Independent of `remaining`, never derived from it: a 429 may omit the header, and this is the signal to branch on. */
	throttledForMs: number | null,
	throttleKind: string | null,
};

/**  One row of the panel's traffic list. */
export type RequestLogEntry = {
	/**  Monotonic within a session, so the panel has a stable React key. */
	seq: number,
	/**  The caller's name for itself, so the panel can say which screen or pass spent the budget. */
	source: string,
	/**  The root field asked for. Never the variables — see `operation_name`. */
	operation: string,
	startedAgoMs: number,
	durationMs: number,
	/**  How long this request waited on the client's own pacing; separate from `durationMs`, since the fixes differ. */
	pacedMs: number,
	status: number | null,
	remainingAfter: number | null,
	/**  `"ok" | "throttled" | "error"`. */
	outcome: string,
};

export type ScanSummary = ScanSummary_Serialize | ScanSummary_Deserialize;

export type ScanSummary_Deserialize = {
	entries: LibraryEntry_Deserialize[],
	/**  Total video files seen (matched or not). */
	files: number,
	matched: number,
};

export type ScanSummary_Serialize = {
	entries: LibraryEntry_Serialize[],
	/**  Total video files seen (matched or not). */
	files: number,
	matched: number,
};

export type ScrobbleSettings = {
	enabled: boolean,
	/**  true = require confirmation in the UI before updating */
	confirm: boolean,
	/**  threshold in minutes; 0 = automatic (2/3 of the episode length) */
	delayMin: number,
	/**  Whether an episode-gap block lifts itself after the grace period; off by default, since the default is asking. */
	gapAuto: boolean,
};

/**  `/System/Info/Public`, the parts the app uses. */
export type ServerInfo = {
	name: string,
	id: string,
	version: string,
};

/**  One row of the Test-connection diagnostic. */
export type SessionSummary = {
	user: string,
	device: string,
	client: string,
	deviceId: string,
	/**  What that session is playing, or `None` when it is idle. */
	playing: string | null,
	/**  Whether the configured user/device filter accepts this session. */
	matched: boolean,
	/**  Set when the row is a Karasu — this one included — with its platform. */
	karasu: Platform | null,
	/**  Seconds between this row's last activity and this instance's own row, on the server clock; what `yield_to` judges by. */
	activeAgoSec: number | null,
};

export type SplitHint = {
	mediaId: number,
	dstStart: number,
};

export type StaleSettings = {
	enabled: boolean,
	months: number,
};

export type Suggested = {
	mediaId: number,
	score: number,
};

/**  Everything the sync panel renders, at the cost of no AniList request, which is what makes polling it acceptable. */
export type SyncStatus = {
	/**  Signed in to AniList; false in local mode, where an empty queue is not the same statement. */
	connected: boolean,
	draining: boolean,
	queued: QueuedEdit[],
	rate: RateSnapshot,
	/**  Recent AniList traffic, newest first, so the panel can show what moved the headroom. */
	recent: RequestLogEntry[],
	/**  Requests per source since the app started, so the panel can say who is spending the budget. */
	traffic: TrafficSnapshot,
};

/**  The parse a correction is keyed on: what the release name said it was. */
export type TitleKey = {
	title: string,
	season: number,
	/**  Whether this parse carries a correction; always computed by `reindex`, since nothing deserializes a `TitleKey`. */
	manual?: boolean,
};

/**  What the panel and the diagnostics report see of the tallies. */
export type TrafficSnapshot = {
	/**  Requests per source since the app started, alphabetical. */
	sources: TrafficSource[],
	/**  HTTP 429 answers since the app started. */
	throttled: number,
	remaining: number | null,
	limit: number | null,
};

export type TrafficSource = {
	source: string,
	total: number,
};

/**  Files that parsed to a title the matcher could not place. */
export type UnmatchedGroup = {
	title: string,
	season: number,
	files: LibraryFile[],
	/**  What AniList thinks this is, unconfirmed: the screen shows it greyed and the user decides. */
	suggestion: Suggested | null,
};

export type UpdateInfo = {
	/**  The running app version. */
	current: string,
	/**  Latest published release tag (without a leading "v"), if any. */
	latest: string | null,
	/**  Release page URL. */
	url: string | null,
	isNewer: boolean,
	/**  The selected channel has no release to compare against, which is not the same as "up to date". */
	channelEmpty: boolean,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

